-- Fix wording (Kyle): Baseline/Weekender/Adventurer/Overlander are common
-- CONFIGURATIONS, not prebuilt inventory. Everything is made-to-order.
update deal_archetypes set signals = array['Transcript keywords: kids, family, wife, husband, park, road trip, memories, summer','Wants Awning, Gear Vault w/ tables, Propane Tank Mount, Roof Vent Fan, 3-Zone Lighting, side/rear windows','Half-ton+ fitment: F150, Tundra, Silverado/Sierra 1500, Ram 1500','Leans toward a Weekender / Adventurer style build']::text[], updated_at = now() where key = 'overland_family';
update deal_archetypes set signals = array['Transcript keywords: weekend, quick trip, after work, easy, value','Loves the 15-second setup + lift-away platform; leans a Baseline / Weekender style build','Dual-use daily driver; midsize or half-ton (Tacoma, F150, 1500)','Evening / weekend engagement timing']::text[], updated_at = now() where key = 'weekend_warrior';
update deal_archetypes set signals = array['Transcript keywords: off-grid, self-sufficient, redundancy, prepared, independent, water, power','Stacks Power Plate + 520W Solar + 105Ah battery + 10gal Water Tank + Propane + MOLLE','Leans an Overlander-style build (full power/solar)','Capability over comfort in questions']::text[], updated_at = now() where key = 'self_reliant';
update deal_archetypes set signals = array['Transcript keywords: best, premium, top of the line, fully loaded, custom, nicest','Wants a fully-loaded Overlander-style build + most accessories','Values made-to-order customization + modern look (integrated brake light, finish)','Low price sensitivity']::text[], updated_at = now() where key = 'status_lifestyle';
update profile_attributes set name = 'Configuration lean', description = 'Which common build configuration they gravitate to — maps to power/solar level. All campers are made-to-order; these are not prebuilt inventory.', updated_at = now() where key = 'prebuild_tier';